"use client";

import { forwardRef, useCallback, useImperativeHandle, useRef } from "react";
import { motion, useAnimate } from "motion/react";

import type { AnimatedIconHandle, AnimatedIconProps } from "./types";

const GithubCopilotIcon = forwardRef<AnimatedIconHandle, AnimatedIconProps>(
  (
    { size = 24, color = "currentColor", strokeWidth = 2, className = "" },
    ref,
  ) => {
    const [scope, animate] = useAnimate();
    const isAnimatingRef = useRef(false);

    const start = useCallback(async () => {
      if (isAnimatingRef.current) return;
      isAnimatingRef.current = true;

      // Reset to replay reveal each hover.
      await animate(
        ".copilot-outline, .eye-left, .eye-right",
        { opacity: 0, pathLength: 0, filter: "blur(0.9px)" },
        { duration: 0 },
      );
      await animate(".copilot-group", { scale: 0.985, rotate: 0 }, { duration: 0 });

      // Subtle fade + draw reveal for the body.
      await animate(
        ".copilot-outline",
        {
          opacity: [0.15, 1],
          pathLength: [0, 1],
          filter: ["blur(0.9px)", "blur(0px)"],
        },
        {
          duration: 0.58,
          ease: [0.22, 1, 0.36, 1],
        },
      );

      // Eyes appear right after shell to feel alive.
      await animate(
        ".eye-left, .eye-right",
        {
          opacity: [0, 1],
          pathLength: [0, 1],
          filter: ["blur(0.9px)", "blur(0px)"],
        },
        { duration: 0.2, ease: "easeOut" },
      );

      // Tiny settle to finish the reveal.
      animate(
        ".copilot-group",
        { scale: [0.985, 1.02, 1] },
        { duration: 0.28, ease: "easeOut" },
      );

      // Hover loop: occasional blink + micro bob.
      while (isAnimatingRef.current) {
        await animate(
          ".eye-left, .eye-right",
          { scaleY: [1, 0.1, 1] },
          { duration: 0.16, ease: "easeInOut" },
        );

        if (!isAnimatingRef.current) break;

        await animate(
          ".copilot-group",
          { y: [0, -0.6, 0] },
          { duration: 0.35, ease: "easeInOut" },
        );

        await new Promise((resolve) =>
          setTimeout(resolve, 900 + Math.random() * 1500),
        );
      }
    }, [animate]);

    const stop = useCallback(() => {
      isAnimatingRef.current = false;

      animate(".copilot-group", { scale: 1, rotate: 0, y: 0 }, { duration: 0.2 });
      animate(
        ".copilot-outline, .eye-left, .eye-right",
        {
          opacity: 1,
          pathLength: 1,
          filter: "blur(0px)",
        },
        { duration: 0.2, ease: "easeOut" },
      );
      animate(".eye-left, .eye-right", { scaleY: 1 }, { duration: 0.18 });
    }, [animate]);

    useImperativeHandle(ref, () => ({
      startAnimation: start,
      stopAnimation: stop,
    }));

    return (
      <motion.div
        ref={scope}
        className={`inline-flex cursor-pointer items-center justify-center ${className}`}
        onHoverStart={start}
        onHoverEnd={stop}
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width={size}
          height={size}
          viewBox="0 0 24 24"
          fill="none"
          stroke={color}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
          style={{ overflow: "visible" }}
        >
          <path stroke="none" d="M0 0h24v24H0z" fill="none" />
          <motion.g className="copilot-group" style={{ transformOrigin: "50% 50%" }}>
            <motion.path
              className="copilot-outline"
              d="M4 18v-5.5c0 -.667 .167 -1.333 .5 -2"
              initial={{ opacity: 1, pathLength: 1 }}
            />
            <motion.path
              className="copilot-outline"
              d="M12 7.5c0 -1 -.01 -4.07 -4 -3.5c-3.5 .5 -4 2.5 -4 3.5c0 1.5 0 4 3 4c4 0 5 -2.5 5 -4z"
              initial={{ opacity: 1, pathLength: 1 }}
            />
            <motion.path
              className="copilot-outline"
              d="M4 12c-1.333 .667 -2 1.333 -2 2c0 1 0 3 1.5 4c3 2 6.5 3 8.5 3s5.499 -1 8.5 -3c1.5 -1 1.5 -3 1.5 -4c0 -.667 -.667 -1.333 -2 -2"
              initial={{ opacity: 1, pathLength: 1 }}
            />
            <motion.path
              className="copilot-outline"
              d="M20 18v-5.5c0 -.667 -.167 -1.333 -.5 -2"
              initial={{ opacity: 1, pathLength: 1 }}
            />
            <motion.path
              className="copilot-outline"
              d="M12 7.5l0 -.297l.01 -.269l.027 -.298l.013 -.105l.033 -.215c.014 -.073 .029 -.146 .046 -.22l.06 -.223c.336 -1.118 1.262 -2.237 3.808 -1.873c2.838 .405 3.703 1.797 3.93 2.842l.036 .204c0 .033 .01 .066 .013 .098l.016 .185l0 .171l0 .49l-.015 .394l-.02 .271c-.122 1.366 -.655 2.845 -2.962 2.845c-3.256 0 -4.524 -1.656 -4.883 -3.081l-.053 -.242a3.865 3.865 0 0 1 -.036 -.235l-.021 -.227a3.518 3.518 0 0 1 -.007 -.215z"
              initial={{ opacity: 1, pathLength: 1 }}
            />
            <motion.path
              className="eye-left"
              d="M10 15v2"
              style={{ transformOrigin: "10px 16px" }}
              initial={{ opacity: 1, pathLength: 1 }}
            />
            <motion.path
              className="eye-right"
              d="M14 15v2"
              style={{ transformOrigin: "14px 16px" }}
              initial={{ opacity: 1, pathLength: 1 }}
            />
          </motion.g>
        </svg>
      </motion.div>
    );
  },
);

GithubCopilotIcon.displayName = "GithubCopilotIcon";

export default GithubCopilotIcon;

import type { SVGMotionProps } from "motion/react";
import type { ComponentType } from "react";

export type HoverlyIconCategory = "All" | "Social" | "UI" | "Arrows";

export interface AnimatedIconHandle {
  startAnimation: () => void | Promise<void>;
  stopAnimation: () => void | Promise<void>;
}

export interface AnimatedIconProps
  extends Omit<SVGMotionProps<SVGSVGElement>, "ref"> {
  size?: number;
  color?: string;
  strokeWidth?: number;
  className?: string;
}

export type HoverlyIconProps = AnimatedIconProps;

export interface IconCliCommand {
  label: string;
  command: string;
}

export interface HoverlyIconRecord {
  slug: string;
  name: string;
  category: Exclude<HoverlyIconCategory, "All">;
  description: string;
  tags: string[];
  componentName: string;
  importPath: string;
  sourceCode: string;
  registryUrl: string;
  cliCommands: IconCliCommand[];
}

export type HoverlyIconComponent = ComponentType<AnimatedIconProps>;
